head.script:
scwin.onpageload = function() {

};

scwin.trigger1_onclick = function(e) {
    var info = {
        inputType : "textarea"
    }
    grd_1.setCellInputType(0, "col1", info)
	console.log("btn1 event")
};

scwin.trigger2_onclick = function(e) {
    var info = {
        inputType : "textarea"
    }
    grd_1.setCellInputType(1, "col1", info)
	console.log("btn2 event")
};

	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}	
	scwin.checkVal1 = function() {
		return scwin.findLastRowIndex() > 12;
	}
	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('G_'+$p.id+'grd_1__dynamic_textarea_0_0').style.display == 'block';
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('G_'+$p.id+'grd_1__dynamic_textarea_0_0').style.display == 'none';
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd_1_cell_0_0')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd_1_column2')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd_1_column2')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd_1_cell_3_0')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");			

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_1_cell_3_2').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
